{
  "findings": [
    {
      "check_id": "CKV_AZURE_67",
      "title": "Function App does not use the latest HTTP version",
      "resource": "azurerm_function_app.changeme_simple_function_app",
      "severity": "MEDIUM",
      "explanation": "The Function App does not enable HTTP/2, leaving it configured to use an older HTTP protocol version."
    },
    {
      "check_id": "CKV_AZURE_70",
      "title": "Function App does not enforce HTTPS",
      "resource": "azurerm_function_app.changeme_simple_function_app",
      "severity": "MEDIUM",
      "explanation": "The resource does not set https_only, so clients may access the Function App over unencrypted HTTP and expose data in transit."
    },
    {
      "check_id": "CKV_AZURE_56",
      "title": "Function App authentication is not enabled",
      "resource": "azurerm_function_app.changeme_simple_function_app",
      "severity": "MEDIUM",
      "explanation": "No authentication settings are configured, allowing unauthenticated requests to reach the Function App unless authorization is implemented separately in application code."
    }
  ],
  "patched_code": "resource \"azurerm_function_app\" \"changeme_simple_function_app\" {\n  name                       = \"changeme-simple-function-app-name\"\n  location                   = azurerm_resource_group.changeme_simple_function_app_resource_group.location\n  resource_group_name        = azurerm_resource_group.changeme_simple_function_app_resource_group.name\n  app_service_plan_id        = azurerm_app_service_plan.changeme_simple_function_app_app_service_plan.id\n  storage_account_name       = azurerm_storage_account.changeme_simple_function_app_storage_account.name\n  storage_account_access_key = azurerm_storage_account.changeme_simple_function_app_storage_account.primary_access_key\n  https_only                 = true\n\n  site_config {\n    http2_enabled = true\n  }\n\n  auth_settings {\n    enabled                       = true\n    unauthenticated_client_action = \"Return401\"\n  }\n}\n",
  "fix_summary": "Enforced HTTPS, enabled HTTP/2, and enabled platform authentication with unauthenticated requests rejected using HTTP 401 responses."
}
